head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst80401";
scwin.AKCDiv = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.AKCDiv = $c.util.getComponent('AKCDiv');
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst80401.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        akc_init();
        scwin.fnInit();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst80401.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_AKCKwd_onblur
 * @description ipt_AKCKwd 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_AKCKwd_onblur = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        chkValidChar(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst80401.ipt_AKCKwd_onblur' }); }
};

/**
 * @method
 * @name input_38_onfocus
 * @description 「닫기」 포커스 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_38_onfocus = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.blur()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst80401.input_38_onfocus' }); }
};

/**
 * @method
 * @name btn_findStockIsu_onclick
 * @description btn_findStockIsu 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_findStockIsu_onclick = function(e){
    try {
        findStockIsu(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst80401.btn_findStockIsu_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearch_onclick
 * @description btn_fnSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearch_onclick = async function(e){
    try {
        await scwin.fnSearch(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst80401.btn_fnSearch_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownload_onclick
 * @description btn_fnDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownload_onclick = async function(e){
    try {
        await scwin.fnDownload(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst80401.btn_fnDownload_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/valueup/invstindicstocks.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/valueup/invstindicstocks.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            await scwin.fnSearch();
        }
    }
};

/**
 * @method
 * @name fnInit
 * @description fn Init 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnInit = function () {
    scwin.fnSearchInit();
};

/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchInit = function () {
    scwin.fnOrder("1", "D");
    if ($c.util.getComponent('AKCDiv').show()) {
        scwin.AKCDiv.setStyle("display", "none");
    }
};

/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {void}
 * @hidden N
 */
scwin.fnOrder = function (mode, stat) {
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    scwin.fnSearchInit();
    if (!$c.util.getComponent('ipt_isuKorAbbrv').getValue()) {
        await $c.win.alert("종목명을 입력해주세요.");
        return;
    }
    if (!($c.util.getComponent("dma_fnDownloadReq").get("isuCd") || '')) {
        await scwin.fnSearchIsuCd();
        return;
    }
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "valueupInvstIndicRankIsuSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "valueupInvstIndicRankIsu_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    const cnt = 6;
    $("#mainContents").empty().append(data);
    $("tr:even").addClass("active");
    for (let i = 1; i <= $("td.dynamic").length / cnt; i++) {
        for (let j = 0; j < cnt; j++) {
            if ($("td.dynamic." + i + "_" + j)) {
                const val = $("td.dynamic." + i + "_" + j).text();
                $("td.dynamic." + i + "_" + j).addClass(scwin.fnGetClassType(val));
            }
        }
    }
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "valueupInvstIndicRankIsuSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "valueupInvstIndicRankIsu_down");
    await scwin.tx_fnDownload();
};

/**
 * @method
 * @name fnSearchIsuCd
 * @description fn Search Isu Cd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchIsuCd = async function () {
    const isuCd = ($c.util.getComponent("dma_fnDownloadReq").get("isuCd") || '');
    if (isuCd === "") {
        await $c.win.alert("종목명 검색을 이용해 정확한 종목명을 선택해주세요.");
        findStockIsu($c.util.getComponent('ipt_isuKorAbbrv').getValue());
    } else {
        scwin.fnSearchInit();
    }
};

/**
 * @method
 * @name setStockInfo
 * @description set Stock Info 처리
 * @param {*} ipt_marketType ipt_marketType
 * @param {String} ipt_isuSrtCd ipt_isuSrtCd
 * @param {*} ipt_isuKorAbbrv ipt_isuKorAbbrv
 * @param {String} isuCd isuCd
 * @param {String} ipt_indNm ipt_indNm
 * @param {String} ipt_listDd ipt_listDd
 * @returns {void}
 * @hidden N
 */
scwin.setStockInfo = function (ipt_marketType, ipt_isuSrtCd, ipt_isuKorAbbrv, isuCd, ipt_indNm, ipt_listDd) {
    const listDt = ipt_listDd.substring(0, 4) + '-' + ipt_listDd.substring(4, 6) + '-' + ipt_listDd.substring(6, 8);
    $c.util.getComponent('ipt_isuCd').setValue(isuCd);
    $c.util.getComponent('ipt_isuSrtCd').setValue(ipt_isuSrtCd);
    $c.util.getComponent('ipt_isuKorAbbrv').setValue(ipt_isuSrtCd + "/" + ipt_isuKorAbbrv);
    $c.util.getComponent('ipt_indNm').setValue(ipt_indNm);
    $c.util.getComponent('ipt_listDd').setValue(listDt);
    if (ipt_marketType === "1") {
        $c.util.getComponent('ipt_marketType').setValue('KOSPI');
    } else {
        if (ipt_marketType === "2") {
            $c.util.getComponent('ipt_marketType').setValue('KOSDAQ');
        } else {

        }
    }
};

/**
 * @method
 * @name fnGetClassType
 * @description fn Get Class Type 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.fnGetClassType = function (val) {
    if ($c.num.unFormatNumber(val)) {
        return "txr";
    } else {
        return "txc";
    }
};
